// `callHandler` as `@kobalte/utils@2.0.0-alpha.0` declares it, with
// `@solidjs/web`'s `JSX.EventHandlerUnion` reduced to its two shapes: a
// function of the event, or a `[function, data]` pair whose function receives
// the data first. It returns the event's `defaultPrevented`.
// `callHandlerOpen` is its control, with `returns` left open in the contract.
// `readKey` returns its argument's `key`, and `passThrough` its argument.
//
// The signatures are `tsc`-clean for every call `App.tsx` makes, so nothing
// here duplicates a type diagnostic.
interface BaseEvent {
  readonly defaultPrevented: boolean;
}
type EventHandler<E extends BaseEvent> = (event: E) => void;
interface BoundEventHandler<E extends BaseEvent> {
  0: (data: any, event: E) => void;
  1: any;
}
type EventHandlerUnion<E extends BaseEvent> = EventHandler<E> | BoundEventHandler<E>;
export declare function callHandler<E extends BaseEvent>(
  event: E,
  handler: EventHandlerUnion<E> | undefined
): boolean;
export declare function callHandlerOpen<E extends BaseEvent>(
  event: E,
  handler: EventHandlerUnion<E> | undefined
): boolean;
export declare function readKey<T>(options: { key: T }): T;
export declare function passThrough<T>(value: T): T;
